import { MeshBasicNodeMaterial } from 'three/webgpu';
import { mix, uv, color, texture } from 'three/tsl';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

/**
 * @param {any} config
 * @param {any} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container
  const root = new Group();

  // ---------- Backdrop (stage) ----------
  const backdropMaterial = new MeshBasicNodeMaterial();
  // Vertical gradient from ink (top) to paper (bottom)
  backdropMaterial.colorNode = mix(
    color('#16161d'), // ink
    color('#e8ecf2'), // paper
    uv().y
  );

  const backdropGeometry = new PlaneGeometry(7, 6);
  const backdropMesh = new Mesh(backdropGeometry, backdropMaterial);
  backdropMesh.position.set(0, 0, -2.5);
  root.add(backdropMesh);

  // ---------- CTA Textured Plane ----------
  const ctaMaterial = new MeshBasicNodeMaterial();
  ctaMaterial.transparent = true; // ensure alpha works if present

  const ctaGeometry = new PlaneGeometry(2, 1);
  const ctaMesh = new Mesh(ctaGeometry, ctaMaterial);
  root.add(ctaMesh);

  // Load texture (if provided)
  const resources = {
    texture: null,
  };

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      resources.texture = tex;
      ctaMaterial.mapNode = texture(tex);
      // Signal material needs refresh
      ctaMaterial.needsUpdate = true;
    });
  }

  // ---------- Event Handlers Placeholder ----------
  root.userData.handlers = {};

  // ---------- Cleanup ----------
  root.userData.cleanup = () => {
    // Dispose geometry and materials
    root.traverse((obj) => {
      if (obj.isMesh) {
        if (obj.geometry) obj.geometry.dispose();
        if (obj.material) obj.material.dispose();
      }
    });
    // Dispose loaded texture
    if (resources.texture) {
      resources.texture.dispose();
    }
    // Kill any GSAP timelines (none in this node but defensive)
    gsap.globalTimeline.clear();
  };

  return root;
}
